{"command": "cat > /workspace/full_module_builder.py << 'PYEOF'
import json
import subprocess

# Load samples data
with open('/workspace/samples_data.json', 'r') as f:
    samples_data = json.load(f)

# Note to FT2 format
note_map = {
    'C-': 1, 'C#': 2, 'D-': 3, 'D#': 4, 'E-': 5, 'F-': 6,
    'F#': 7, 'G-': 8, 'G#': 9, 'A-': 10, 'A#': 11, 'B-': 12
}

def parse_note(note_str):
    """Parse note like 'A-5' to (note, octave)"""
    note = note_str[:2]
    octave = int(note_str[2])
    return note, octave

# Create the module
commands = []

# 1. Create module
commands.append({"name": "module_new", "arguments": {"channels": 8, "name": "KeyGen Tune 2024"}})

# 2. Set song properties - 150 BPM, speed 6
commands.append({"name": "song_set", "arguments": {"bpm": 150, "speed": 6, "length": 16}})

# 3. Create and load samples
# Instrument 1: Lead
commands.append({"name": "instrument_set", "arguments": {"instrument": 1, "name": "Lead"}})
commands.append({"name": "sample_create_from_pcm", "arguments": {
    "instrument": 1, "sample": 0, "encoding": "int16",
    "pcm": samples_data['lead'],
    "name": "Lead"
}})
commands.append({"name": "sample_set", "arguments": {
    "instrument": 1, "sample": 0, "volume": 64, "panning": 128,
    "loop_start": 0, "loop_length": samples_data['lead_len']
}})

# Instrument 2: Bass
commands.append({"name": "instrument_set", "arguments": {"instrument": 2, "name": "Bass"}})
commands.append({"name": "sample_create_from_pcm", "arguments": {
    "instrument": 2, "sample": 0, "encoding": "int16",
    "pcm": samples_data['bass'],
    "name": "Bass"
}})
commands.append({"name": "sample_set", "arguments": {
    "instrument": 2, "sample": 0, "volume": 64, "panning": 128,
    "loop_start": 0, "loop_length": samples_data['bass_len']
}})

# Instrument 3: Kick
commands.append({"name": "instrument_set", "arguments": {"instrument": 3, "name": "Kick"}})
commands.append({"name": "sample_create_from_pcm", "arguments": {
    "instrument": 3, "sample": 0, "encoding": "int16",
    "pcm": samples_data['kick'],
    "name": "Kick"
}})
commands.append({"name": "sample_set", "arguments": {
    "instrument": 3, "sample": 0, "volume": 64, "panning": 64
}})

# Instrument 4: Hi-hat
commands.append({"name": "instrument_set", "arguments": {"instrument": 4, "name": "HiHat"}})
commands.append({"name": "sample_create_from_pcm", "arguments": {
    "instrument": 4, "sample": 0, "encoding": "int16",
    "pcm": samples_data['hihat'],
    "name": "HiHat"
}})
commands.append({"name": "sample_set", "arguments": {
    "instrument": 4, "sample": 0, "volume": 48, "panning": 192
}})

# Instrument 5: Snare
commands.append({"name": "instrument_set", "arguments": {"instrument": 5, "name": "Snare"}})
commands.append({"name": "sample_create_from_pcm", "arguments": {
    "instrument": 5, "sample": 0, "encoding": "int16",
    "pcm": samples_data['snare'],
    "name": "Snare"
}})
commands.append({"name": "sample_set", "arguments": {
    "instrument": 5, "sample": 0, "volume": 60, "panning": 160
}})

# 4. Define patterns (64 rows each, 3 patterns for variety)
# Pattern 0: Main groove
# Pattern 1: Variation
# Pattern 2: Break/Build

# Melody pattern data - every 2 rows is one beat at speed 6
# We need to fill 64 rows
melody_rows = [
    # Rows 0-15: First phrase (speed 6 = 2 ticks per row)
    ("A-5", 1, 48), (None, None, None), ("C-6", 1, 50), (None, None, None),
    ("E-6", 1, 52), (None, None, None), ("A-6", 1, 57), (None, None, None),
