    ("A-4", 1, 45), (None, None, None), ("C-5", 1, 48), (None, None, None),
    # Rows 32-47: Third phrase - higher intensity
    ("D-5", 1, 50), (None, None, None), ("F-5", 1, 53), (None, None, None),
    ("A-5", 1, 55), (None, None, None), ("D-6", 1, 62), (None, None, None),
