# Drums - Kick on 0, 16, 32, 48; Snare on 8, 24, 40, 56; Hi-hat every 2 rows
drum_rows = [
    # Kick pattern
    ("C-5", 3, 33), (None, None, None), (None, None, None), (None, None, None),
