    "A-5", None, "C-6", None, "E-6", None, "A-6", None,
    "G-5", None, "E-5", None, "C-5", None, "E-5", None,
    "F-5", None, "A-5", None, "C-6", None, "D-6", None,
    "E-6", None, "C-6", None, "A-5", None, "E-5", None,
    "D-5", None, "F-5", None, "A-5", None, "C-6", None,
    "D-6", None, "E-6", None, "C-6", None, "A-5", None,
    "E-5", None, "G-5", None, "A-5", None, "E-6", None,
    "D-6", None, "C-6", None, "A-5", None, "E-5", None,
]

# Bass pattern
bass_main = [
    "A-3", None, None, None, "A-3", None, None, None,
    "F-3", None, None, None, "G-3", None, None, None,
    "D-3", None, None, None, "D-3", None, None, None,
    "E-3", None, None, None, "E-3", None, None, None,
    "A-3", None, None, None, "A-3", None, None, None,
    "F-3", None, None, None, "G-3", None, None, None,
    "D-3", None, None, None, "D-3", None, None, None,
    "E-3", None, None, None, "A-3", None, None, None,
]

# Drums
drums_main = []
for i in range(64):
    if i % 16 == 0:
        drums_main.append((3, "kick"))
    elif i % 16 == 8:
        drums_main.append((4, "snare"))
    elif i % 2 == 0:
        drums_main.append((5, "hihat"))
    else:
        drums_main.append((None, None))

# Pattern 0 - Main groove
for row in range(64):
    add_note_cmd(cmds, 0, row, 0, melody_main[row], 1)
    add_note_cmd(cmds, 0, row, 1, bass_main[row], 2)

    inst, name = drums_main[row]
    if inst:
        ch = {3: 2, 4: 3, 5: 4}[inst]
        cmds.append({"name": "pattern_set_cell", "arguments": {
            "pattern": 0, "row": row, "channel": ch, "note": 48, "instrument": inst
        }})

# Pattern 1 - Arpeggio variation
arpeggio = ["A-5", "C-6", "E-6", "C-6", "A-5", "C-6", "E-6", "C-6"]
for row in range(64):
    add_note_cmd(cmds, 1, row, 0, arpeggio[row % 8], 1)
    add_note_cmd(cmds, 1, row, 1, bass_main[row], 2)

    inst, name = drums_main[row]
    if inst:
        ch = {3: 2, 4: 3, 5: 4}[inst]
        cmds.append({"name": "pattern_set_cell", "arguments": {
            "pattern": 1, "row": row, "channel": ch, "note": 48, "instrument": inst
        }})

# Pattern 2 - Breakdown (sparse)
for row in range(64):
    if row % 16 == 0:
        add_note_cmd(cmds, 2, row, 0, melody_main[row], 1)
        add_note_cmd(cmds, 2, row, 1, bass_main[row], 2)
        cmds.append({"name": "pattern_set_cell", "arguments": {
            "pattern": 2, "row": row, "channel": 2, "note": 48, "instrument": 3
        }})

# Pattern 3 - Build-up (intense)
for row in range(64):
    add_note_cmd(cmds, 3, row, 0, melody_main[row], 1)
    add_note_cmd(cmds, 3, row, 1, bass_main[row], 2)

    inst, name = drums_main[row]
    if inst:
        ch = {3: 2, 4: 3, 5: 4}[inst]
        cmds.append({"name": "pattern_set_cell", "arguments": {
            "pattern": 3, "row": row, "channel": ch, "note": 48, "instrument": inst
        }})

    # Extra hi-hats in the build
    if row % 2 == 1 and row < 56:
        cmds.append({"name": "pattern_set_cell", "arguments": {
            "pattern": 3, "row": row, "channel": 5, "note": 48, "instrument": 5
        }})

# 6. Order list
order_patterns = [0, 0, 1, 2, 3, 1, 0, 3]
for i, p in enumerate(order_patterns):
    cmds.append({"name": "order_set", "arguments": {"position": i, "pattern": p}})

# Save commands
with open('/workspace/enhanced_commands.json', 'w') as f:
    json.dump(cmds, f)

print(f"Generated {len(cmds)} commands")
